/* Sales Management Module - standalone MVP sharing the Purchase Management localStorage store. */
function salesSeed(x){
  if(!Array.isArray(x.customers)) x.customers=[
    {id:1,code:'CUS-001',name:'ABC Traders',contact:'Ahmed Khan',phone:'0300-5550001',email:'sales@abc.test',address:'Karachi',category:'Retail',paymentTerms:'30 Days',creditLimit:500000,status:'Active'},
    {id:2,code:'CUS-002',name:'City Office Solutions',contact:'Sara Ali',phone:'0301-5550002',email:'accounts@cityoffice.test',address:'Lahore',category:'Corporate',paymentTerms:'15 Days',creditLimit:300000,status:'Active'},
    {id:3,code:'CUS-003',name:'Tech Hub',contact:'Usman Raza',phone:'0302-5550003',email:'info@techhub.test',address:'Islamabad',category:'Wholesale',paymentTerms:'Cash',creditLimit:200000,status:'Active'}
  ];
  ['salesQuotations','salesOrders','deliveries','customerInvoices','customerPayments'].forEach(k=>{if(!Array.isArray(x[k]))x[k]=[]});
  return x;
}
function sdb(){return salesSeed(db())}
function salesNo(prefix,arr,key){let n=arr.reduce((m,a)=>Math.max(m,Number(String(a[key]||'').split('-').pop())||0),0)+1;return prefix+'-2026-'+String(n).padStart(3,'0')}
function salesStock(x,productId){
  const received=(x.receipts||[]).reduce((n,r)=>(r.items||[]).reduce((m,i)=>m+(Number(i.productId)===Number(productId)?Number(i.acceptedQty||0):0),n),0);
  const delivered=(x.deliveries||[]).reduce((n,d)=>(d.items||[]).reduce((m,i)=>m+(Number(i.productId)===Number(productId)?Number(i.deliveredQty||0):0),n),0);
  return Math.max(0,received-delivered);
}
function salesTotal(items){return items.reduce((n,i)=>n+Number(i.total||0),0)}
function calcSalesItem(qty,rate,discount,tax){const gross=Number(qty||0)*Number(rate||0), disc=gross*Number(discount||0)/100, taxable=gross-disc, taxAmt=taxable*Number(tax||0)/100;return {gross,discountAmount:disc,taxAmount:taxAmt,total:taxable+taxAmt}}
function renderSalesDashboard(){
  if(!guard('sales'))return;
  const x=sdb(),u=currentUser(),orders=x.salesOrders||[],quotes=x.salesQuotations||[],customers=x.customers||[],deliveries=x.deliveries||[],invoices=x.customerInvoices||[],payments=x.customerPayments||[];
  const openOrders=orders.filter(o=>!['Completed','Cancelled'].includes(String(o.status||''))), unpaid=invoices.filter(i=>i.status!=='Paid'), accepted=quotes.filter(q=>q.status==='Accepted'), sent=quotes.filter(q=>['Sent','Accepted'].includes(q.status));
  const orderValue=orders.reduce((s,o)=>s+Number(o.total||0),0),outstanding=unpaid.reduce((s,i)=>s+Math.max(0,Number(i.balance??(Number(i.amount||i.total||0)-Number(i.paidAmount||0)))),0),paid=payments.reduce((s,p)=>s+Number(p.amount||0),0),pendingDelivery=deliveries.filter(d=>d.status!=='Delivered').length;
  const monthly=Array.from({length:6},(_,i)=>{const d=new Date();d.setMonth(d.getMonth()-(5-i));const m=d.getMonth(),y=d.getFullYear();return orders.filter(o=>{const dt=new Date(o.orderDate||o.createdAt||'');return !Number.isNaN(dt.getTime())&&dt.getMonth()===m&&dt.getFullYear()===y}).reduce((s,o)=>s+Number(o.total||0),0)}),max=Math.max(...monthly,1),pts=monthly.map((v,i)=>`${30+i*120},${150-(v/max)*105}`).join(' '),labels=monthly.map((_,i)=>{const d=new Date();d.setMonth(d.getMonth()-(5-i));return d.toLocaleDateString(undefined,{month:'short'})});
  const svg=`<svg class="module-chart" viewBox="0 0 780 185" role="img" aria-label="Sales order value trend"><g class="grid">${[25,60,95,130,155].map(y=>`<line x1="30" x2="750" y1="${y}" y2="${y}"/>`).join('')}</g><polyline class="module-line" points="${pts}"/>${monthly.map((v,i)=>`<circle class="module-dot" cx="${30+i*120}" cy="${150-(v/max)*105}" r="4"/>`).join('')}${labels.map((m,i)=>`<text x="${30+i*120}" y="174" text-anchor="middle">${m}</text>`).join('')}</svg>`;
  const funnel=[['Draft',quotes.filter(q=>q.status==='Draft').length],['Pending Approval',quotes.filter(q=>q.status==='Pending Approval').length],['Approved',quotes.filter(q=>q.status==='Approved').length],['Sent',sent.length],['Accepted',accepted.length]],maxF=Math.max(...funnel.map(a=>a[1]),1);
  const status=[['Open Orders',openOrders.length,'ti-shopping-cart'],['Pending Deliveries',pendingDelivery,'ti-truck-delivery'],['Unpaid Invoices',unpaid.length,'ti-file-invoice'],['Payments Received',payments.length,'ti-cash']];
  const recent=orders.slice(0,6),maxRecent=Math.max(...recent.map(o=>Number(o.total||0)),1);
  layout('sales','Sales Dashboard','Sales performance, customer orders, fulfillment and receivables',`<div class="module-dashboard">
    <div class="module-hero"><div class="module-hero-copy"><span class="module-eyebrow"><i class="ti ti-chart-line"></i> Sales command view</span><h2>Sales Performance Center</h2><p>Track quotations, orders, fulfillment and customer collections from one view.</p><div class="module-hero-meta"><span><i class="ti ti-users"></i> ${customers.length} customers</span><span><i class="ti ti-file-dollar"></i> ${quotes.length} quotations</span><span><i class="ti ti-shopping-cart"></i> ${openOrders.length} open orders</span></div></div><div class="module-orb"><div class="module-orb-ring"></div><div class="module-orb-ring r2"></div><div class="module-orb-core"><i class="ti ti-chart-dots"></i></div></div></div>
    <div class="module-kpi-grid"><div class="module-kpi blue"><div class="module-kpi-top"><span>Sales Order Value</span><i class="ti ti-cash"></i></div><strong>${money(orderValue)}</strong><small>Total confirmed order value</small></div><div class="module-kpi purple"><div class="module-kpi-top"><span>Open Orders</span><i class="ti ti-shopping-cart"></i></div><strong>${openOrders.length}</strong><small>Orders still in fulfillment</small></div><div class="module-kpi green"><div class="module-kpi-top"><span>Collected</span><i class="ti ti-circle-check"></i></div><strong>${money(paid)}</strong><small>Customer payments received</small></div><div class="module-kpi amber"><div class="module-kpi-top"><span>Receivables</span><i class="ti ti-file-invoice"></i></div><strong>${money(outstanding)}</strong><small>Outstanding customer balance</small></div></div>
    <div class="module-grid-2"><div class="module-panel"><div class="module-panel-head"><div><span class="module-kicker">Performance</span><h3>Sales Order Trend</h3><p>Confirmed order value over the last six months</p></div><span class="module-pill">${money(orderValue)} total</span></div>${svg}</div><div class="module-panel"><div class="module-panel-head"><div><span class="module-kicker">Quotation funnel</span><h3>Quote Progress</h3><p>From draft to customer acceptance</p></div><div class="module-badge">${quotes.length}</div></div><div class="module-bars">${funnel.map(([label,val])=>`<div class="module-bar-row"><div class="module-bar-label"><span>${label}</span><b>${val}</b></div><div class="module-track green"><span style="width:${Math.max(5,val/maxF*100)}%"></span></div></div>`).join('')}</div><div class="module-foot"><span class="good">${accepted.length} accepted</span><span class="warn">${quotes.filter(q=>q.status==='Rejected').length} rejected</span><span>${quotes.length?Math.round(accepted.length/quotes.length*100):0}% acceptance</span></div></div></div>
    <div class="module-grid-3"><div class="module-panel"><div class="module-panel-head"><div><span class="module-kicker">Operations</span><h3>Sales Health</h3><p>Live work in progress</p></div></div><div class="module-mini-grid">${status.map(([label,val,icon])=>`<div class="module-mini"><i class="ti ${icon}"></i><b>${val}</b><span>${label}</span></div>`).join('')}</div></div>
      <div class="module-panel"><div class="module-panel-head"><div><span class="module-kicker">Orders</span><h3>Recent Orders</h3><p>Highest recent order values</p></div><a class="module-action" href="sales-orders.html">View orders</a></div><div class="module-bars">${recent.length?recent.map(o=>`<div class="module-bar-row"><div class="module-bar-label"><span>${esc(o.orderNo||'Order')} · ${esc(o.customerName||'Customer')}</span><b>${money(o.total)}</b></div><div class="module-track"><span style="width:${Math.max(6,Number(o.total||0)/maxRecent*100)}%"></span></div></div>`).join(''):'<div class="module-empty">No sales orders yet.</div>'}</div></div>
      <div class="module-panel"><div class="module-panel-head"><div><span class="module-kicker">Fulfillment</span><h3>Delivery Status</h3><p>Customer orders in dispatch</p></div><a class="module-action" href="sales-deliveries.html">Deliveries</a></div><div class="module-mini-grid"><div class="module-mini"><i class="ti ti-truck-delivery"></i><b>${deliveries.length}</b><span>Total deliveries</span></div><div class="module-mini"><i class="ti ti-circle-check"></i><b>${deliveries.filter(d=>d.status==='Delivered').length}</b><span>Delivered</span></div><div class="module-mini"><i class="ti ti-clock"></i><b>${pendingDelivery}</b><span>Pending</span></div><div class="module-mini"><i class="ti ti-receipt"></i><b>${unpaid.length}</b><span>Invoices unpaid</span></div></div></div></div>
    <div class="module-panel"><div class="module-panel-head"><div><span class="module-kicker">Collections</span><h3>Customer Receivables</h3><p>Invoice and payment position</p></div><a class="module-action" href="sales-invoices.html">View invoices</a></div><div class="module-list">${unpaid.slice(0,6).map(i=>`<div class="module-list-row"><span class="module-list-icon"><i class="ti ti-file-invoice"></i></span><div><b>${esc(i.invoiceNo||'Invoice')} · ${esc(i.customerName||'Customer')}</b><small>Due ${esc(i.dueDate||'—')} · ${esc(i.status||'Open')}</small></div><strong>${money(Math.max(0,Number(i.balance??(Number(i.amount||i.total||0)-Number(i.paidAmount||0)))) )}</strong></div>`).join('')||'<div class="module-empty">No outstanding customer invoices.</div>'}</div></div>
  </div>`);
}
function renderCustomers(){if(!guard('sales_customers'))return;const x=sdb(),u=currentUser();let rows=x.customers;if(u?.role==='Sales Manager')rows=rows.filter(c=>(x.leads||[]).some(l=>Number(l.customerId)===Number(c.id)&&String(l.managerId)===String(u.id)));else if(['Salesperson','Sales Representative'].includes(u?.role))rows=rows.filter(c=>(x.leads||[]).some(l=>Number(l.customerId)===Number(c.id)&&String(l.ownerId)===String(u.id)));layout('customers','Customers','Customer master data shared by CRM and Sales',`<div class="section-card"><div class="section-head"><div><div class="section-title">Customer List</div><div class="hint">Customers shared by Sales and Accounting</div></div><button class="btn-primary" onclick="openCustomer()"><i class="ti ti-plus"></i> Add Customer</button></div><div class="filters"><input id="cust-search" placeholder="Search customer, code, phone" oninput="filterCustomers()"></div><div id="cust-table">${customerRows(rows)}</div></div>`)}
function filterCustomers(){const x=sdb(),q=(document.getElementById('cust-search')?.value||'').toLowerCase();document.getElementById('cust-table').innerHTML=customerRows(x.customers.filter(c=>(c.name+' '+c.code+' '+c.phone+' '+c.email).toLowerCase().includes(q)))}
function openCustomer(){openModal(formModal('Add Customer',`<div class="grid2"><label>Customer Name<input id="cname"></label><label>Contact Person<input id="ccontact"></label><label>Phone<input id="cphone"></label><label>Email<input id="cemail" type="email"></label><label>Category<input id="ccat" placeholder="Corporate / Retail / Wholesale"></label><label>Payment Terms<select id="cterms"><option>Cash</option><option>15 Days</option><option>30 Days</option><option>45 Days</option></select></label><label>Credit Limit<input id="climit" type="number" value="0"></label><label>Status<select id="cstatus"><option>Active</option><option>Inactive</option></select></label></div><label>Address<textarea id="caddress" rows="2"></textarea></label>`,'saveCustomer()'))}
function saveCustomer(){const x=sdb(),name=document.getElementById('cname').value.trim();if(!name){toast('Customer name is required');return}x.customers.unshift({id:Date.now(),code:salesNo('CUS',x.customers,'code'),name,contact:ccontact.value.trim(),phone:cphone.value.trim(),email:cemail.value.trim(),category:ccat.value.trim(),paymentTerms:cterms.value,creditLimit:Number(climit.value||0),status:cstatus.value,address:caddress.value.trim()});recordActivity(x,'Created','Sales Customers','Customer added: '+name,'Customer');save(x);closeModal();renderCustomers();toast('Customer added')}
function customerDetails(id){const x=sdb(),c=x.customers.find(a=>a.id===id);if(!c)return;const orders=x.salesOrders.filter(o=>Number(o.customerId)===Number(id));openModal(`<div class="modal" id="modal"><div class="modal-box request-modal"><div class="modal-head"><div><h3>${esc(c.name)}</h3><small>${esc(c.code)}</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="detail-grid">${['contact','phone','email','category','paymentTerms','address'].map(k=>`<div><span>${esc(k)}</span><b>${esc(c[k]||'—')}</b></div>`).join('')}<div><span>Credit Limit</span><b>${money(c.creditLimit)}</b></div><div><span>Status</span><b>${status(c.status)}</b></div></div>${table(['Order','Date','Status','Total'],orders.map(o=>`<tr><td>${esc(o.orderNo)}</td><td>${esc(o.orderDate)}</td><td>${status(o.status)}</td><td>${money(o.total)}</td></tr>`).join(''))}</div><div class="modal-foot"><button class="btn-secondary" onclick="closeModal()">Close</button></div></div></div>`)}
function salesProductOptions(){const x=sdb();return x.products.filter(p=>p.active!==false).map(p=>`<option value="${p.id}">${esc(p.name)} — ${esc(p.sku||'')} — ${money(p.default_rate||p.rate||0)}</option>`).join('')}
function sqItemRow(i=0,item={}){const p=sdb().products.find(a=>Number(a.id)===Number(item.productId));return `<div class="line-item sales-line" data-index="${i}"><select class="s-prod" onchange="syncSalesLine(this)"><option value="">Select product</option>${salesProductOptions()}</select><input class="s-desc" placeholder="Description" value="${esc(item.description||'')}"><input class="s-qty" type="number" min="0.01" step="0.01" value="${item.quantity||1}" oninput="calcSalesForm()"><input class="s-rate" type="number" min="0" step="0.01" value="${item.rate||p?.default_rate||p?.rate||0}" oninput="calcSalesForm()"><input class="s-disc" type="number" min="0" max="100" step="0.01" value="${item.discountPercent||0}" oninput="calcSalesForm()"><input class="s-tax" type="number" min="0" max="100" step="0.01" value="${item.taxPercent==null?salesTaxRate():item.taxPercent}" oninput="calcSalesForm()"><span class="s-total">${money(item.total||0)}</span><button class="icon-btn" onclick="this.closest('.line-item').remove();calcSalesForm()">×</button>${p?`<script>document.currentScript.closest('.line-item').querySelector('.s-prod').value='${p.id}'</script>`:''}</div>`}
function openSalesQuotation(){const x=sdb();if(!x.customers.length){toast('Add a customer first');return}openModal(`<div class="modal" id="modal"><div class="modal-box request-modal wide"><div class="modal-head"><div><h3>New Sales Quotation</h3><small>Prepare a quotation for customer approval</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="grid2"><label>Customer<select id="sq-customer">${x.customers.filter(c=>c.status==='Active').map(c=>`<option value="${c.id}">${esc(c.code)} — ${esc(c.name)}</option>`).join('')}</select></label><label>Quotation Date<input id="sq-date" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Valid Until<input id="sq-valid" type="date"></label><label>Payment Terms<select id="sq-terms"><option>Cash</option><option>15 Days</option><option>30 Days</option><option>45 Days</option></select></label><label>Delivery Terms<input id="sq-delivery" placeholder="e.g. 7 working days"></label><label>Tax Type<input id="sq-taxnote" value="${esc(salesTaxLabel())}" placeholder="Sales Tax / GST / Exempt"></label></div><div class="line-head"><b>Items</b><button class="btn-sm" onclick="addSalesLine()"><i class="ti ti-plus"></i> Add Item</button></div><div class="line-grid-head"><span>Product</span><span>Description</span><span>Qty</span><span>Rate</span><span>Disc %</span><span>${esc(salesTaxLabel())} %</span><span>Total</span><span></span></div><div id="sales-lines">${sqItemRow(0,{})}</div><div class="request-summary"><span>Quotation Total</span><strong id="sq-total">${money(0)}</strong></div><label>Terms & Conditions<textarea id="sq-termsnote" rows="3"></textarea></label><label>Notes<textarea id="sq-notes" rows="2"></textarea></label></div><div class="modal-foot"><button class="btn-secondary" onclick="closeModal()">Cancel</button><button class="btn-primary" onclick="saveSalesQuotation('Draft')">Save Draft</button><button class="btn-primary" onclick="saveSalesQuotation('Sent')"><i class="ti ti-send"></i> Save & Send</button></div></div></div>`);calcSalesForm()}
function addSalesLine(){document.getElementById('sales-lines').insertAdjacentHTML('beforeend',sqItemRow(document.querySelectorAll('.sales-line').length,{}))}
function syncSalesLine(sel){const row=sel.closest('.sales-line'),p=sdb().products.find(a=>Number(a.id)===Number(sel.value));if(p)row.querySelector('.s-rate').value=p.default_rate||p.rate||0;calcSalesForm()}
function collectSalesLines(){return [...document.querySelectorAll('.sales-line')].map(r=>{const p=sdb().products.find(a=>Number(a.id)===Number(r.querySelector('.s-prod').value));const qty=Number(r.querySelector('.s-qty').value||0),rate=Number(r.querySelector('.s-rate').value||0),disc=Number(r.querySelector('.s-disc').value||0),tax=Number(r.querySelector('.s-tax').value||0),c=calcSalesItem(qty,rate,disc,tax);return{productId:p?.id||null,productName:p?.name||'',sku:p?.sku||'',unit:p?.unit||'',description:r.querySelector('.s-desc').value.trim(),quantity:qty,rate,discountPercent:disc,taxPercent:tax,...c}}).filter(i=>i.productId&&i.quantity>0)}
function calcSalesForm(){const items=collectSalesLines();items.forEach((it,i)=>{const r=document.querySelectorAll('.sales-line')[i];if(r)r.querySelector('.s-total').textContent=money(it.total)});const el=document.getElementById('sq-total');if(el)el.textContent=money(salesTotal(items))}
function saveSalesQuotation(targetStatus){const x=sdb(),items=collectSalesLines();if(!items.length){toast('Add at least one product');return}const customer=x.customers.find(c=>Number(c.id)===Number(document.getElementById('sq-customer').value));const total=salesTotal(items);const q={id:Date.now(),quotationNo:salesNo('SQ',x.salesQuotations,'quotationNo'),customerId:customer.id,customerName:customer.name,quotationDate:document.getElementById('sq-date').value,validUntil:document.getElementById('sq-valid').value||null,paymentTerms:document.getElementById('sq-terms').value,deliveryTerms:document.getElementById('sq-delivery').value.trim(),taxNote:document.getElementById('sq-taxnote').value.trim(),items,total,status:targetStatus,terms:document.getElementById('sq-termsnote').value.trim(),notes:document.getElementById('sq-notes').value.trim(),createdAt:new Date().toISOString()};x.salesQuotations.unshift(q);recordActivity(x,'Created','Sales Quotations','Sales quotation '+q.quotationNo+' created for '+customer.name,'Sales Quotation');save(x);closeModal();renderSalesQuotations();toast(targetStatus==='Sent'?'Quotation saved and marked Sent':'Quotation saved as Draft')}
function salesQuotationRows(rows){return table(['Quotation','Customer','Date','Valid Until','Status','Total','Actions'],rows.map(q=>`<tr><td><button class="link-btn" onclick="salesQuotationDetails(${q.id})">${esc(q.quotationNo)}</button></td><td>${esc(q.customerName)}</td><td>${esc(q.quotationDate)}</td><td>${esc(q.validUntil||'—')}</td><td>${status(q.status)}</td><td>${money(q.total)}</td><td>${q.status==='Sent'?`<button class="btn-sm" onclick="acceptSalesQuotation(${q.id})"><i class="ti ti-check"></i> Accept</button>`:''} ${['Draft','Sent'].includes(q.status)?`<button class="btn-sm" onclick="rejectSalesQuotation(${q.id})">Reject</button>`:''}</td></tr>`).join(''))}
function renderSalesQuotations(){if(!guard('sales_quotations'))return;const x=sdb();layout('sales-quotations','Sales Quotations','Create, send and convert customer quotations',`<div class="section-card"><div class="section-head"><div><div class="section-title">Quotation List</div><div class="hint">Draft → Sent → Accepted / Rejected / Expired</div></div><button class="btn-primary" onclick="openSalesQuotation()"><i class="ti ti-plus"></i> New Quotation</button></div><div class="filters"><input id="sq-search" placeholder="Search quotation or customer" oninput="filterSalesQuotations()"><select id="sq-status" onchange="filterSalesQuotations()"><option value="">All Statuses</option><option>Draft</option><option>Sent</option><option>Accepted</option><option>Rejected</option><option>Expired</option><option>Converted</option></select></div><div id="sq-table">${salesQuotationRows(x.salesQuotations)}</div></div>`)}
function filterSalesQuotations(){const x=sdb(),q=(document.getElementById('sq-search')?.value||'').toLowerCase(),s=document.getElementById('sq-status')?.value||'';document.getElementById('sq-table').innerHTML=salesQuotationRows(x.salesQuotations.filter(a=>(!q||(a.quotationNo+' '+a.customerName).toLowerCase().includes(q))&&(!s||a.status===s)))}
function acceptSalesQuotation(id){const x=sdb(),q=x.salesQuotations.find(a=>a.id===id);if(!q)return;q.status='Accepted';const customer=x.customers.find(c=>Number(c.id)===Number(q.customerId));const order={id:Date.now(),orderNo:salesNo('SO',x.salesOrders,'orderNo'),quotationId:q.id,quotationNo:q.quotationNo,customerId:q.customerId,customerName:q.customerName,orderDate:new Date().toISOString().slice(0,10),items:structuredClone(q.items),total:q.total,status:'Confirmed',deliveryStatus:'Pending',invoiceStatus:'Not Invoiced',paymentStatus:'Unpaid',paymentTerms:q.paymentTerms,deliveryTerms:q.deliveryTerms,createdAt:new Date().toISOString()};x.salesOrders.unshift(order);q.status='Converted';recordActivity(x,'Confirmed','Sales Orders','Sales order '+order.orderNo+' created from '+q.quotationNo,'Sales Order');save(x);renderSalesQuotations();toast('Quotation accepted and converted to Sales Order')}
function rejectSalesQuotation(id){const x=sdb(),q=x.salesQuotations.find(a=>a.id===id);if(q){q.status='Rejected';recordActivity(x,'Rejected','Sales Quotations',q.quotationNo+' rejected','Sales Quotation');save(x);renderSalesQuotations();toast('Quotation rejected')}}
function salesQuotationDetails(id){const x=sdb(),q=x.salesQuotations.find(a=>a.id===id);if(!q)return;openModal(`<div class="modal" id="modal"><div class="modal-box request-modal wide"><div class="modal-head"><div><h3>${esc(q.quotationNo)}</h3><small>${esc(q.customerName)}</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="detail-grid"><div><span>Date</span><b>${esc(q.quotationDate)}</b></div><div><span>Valid Until</span><b>${esc(q.validUntil||'—')}</b></div><div><span>Payment</span><b>${esc(q.paymentTerms)}</b></div><div><span>Status</span><b>${status(q.status)}</b></div></div>${table(['Product','Qty','Rate','Discount','Tax','Total'],q.items.map(i=>`<tr><td>${esc(i.productName)}</td><td>${i.quantity}</td><td>${money(i.rate)}</td><td>${i.discountPercent}%</td><td>${i.taxPercent}%</td><td>${money(i.total)}</td></tr>`).join(''))}<div class="request-summary"><span>Total</span><strong>${money(q.total)}</strong></div>${q.terms?`<div class="detail-note"><b>Terms</b><p>${esc(q.terms)}</p></div>`:''}</div><div class="modal-foot"><button class="btn-secondary" onclick="closeModal()">Close</button>${q.status==='Sent'?`<button class="btn-primary" onclick="closeModal();acceptSalesQuotation(${q.id})">Accept & Create Order</button>`:''}</div></div></div>`)}
function salesOrderRows(rows){return table(['Order','Customer','Date','Status','Delivery','Invoice','Payment','Total','Actions'],rows.map(o=>`<tr><td><button class="link-btn" onclick="salesOrderDetails(${o.id})">${esc(o.orderNo)}</button></td><td>${esc(o.customerName)}</td><td>${esc(o.orderDate)}</td><td>${status(o.status)}</td><td>${status(o.deliveryStatus||'Pending')}</td><td>${status(o.invoiceStatus||'Not Invoiced')}</td><td>${status(o.paymentStatus||'Unpaid')}</td><td>${money(o.total)}</td><td><button class="btn-sm" onclick="openDelivery(${o.id})">Delivery</button> <button class="btn-sm" onclick="createCustomerInvoice(${o.id})">Invoice</button></td></tr>`).join(''))}
function renderSalesOrders(){if(!guard('sales_orders'))return;const x=sdb();layout('sales-orders','Sales Orders','Confirmed customer orders and fulfillment',`<div class="section-card"><div class="section-head"><div><div class="section-title">Sales Order List</div><div class="hint">Confirmed customer orders created from accepted quotations</div></div><button class="btn-primary" onclick="openSalesOrderCreateModal()"><i class="ti ti-plus"></i> Create Sales Order</button></div><div class="filters"><input id="so-search" placeholder="Search order or customer" oninput="filterSalesOrders()"><select id="so-status" onchange="filterSalesOrders()"><option value="">All Statuses</option><option>Confirmed</option><option>Partially Delivered</option><option>Delivered</option><option>Completed</option><option>Cancelled</option></select></div><div id="so-table">${salesOrderRows(x.salesOrders)}</div></div>`)}
function filterSalesOrders(){const x=sdb(),q=(document.getElementById('so-search')?.value||'').toLowerCase(),s=document.getElementById('so-status')?.value||'';document.getElementById('so-table').innerHTML=salesOrderRows(x.salesOrders.filter(a=>(!q||(a.orderNo+' '+a.customerName).toLowerCase().includes(q))&&(!s||a.status===s)))}
function salesOrderDetails(id){const x=sdb(),o=x.salesOrders.find(a=>a.id===id);if(!o)return;openModal(`<div class="modal" id="modal"><div class="modal-box request-modal wide"><div class="modal-head"><div><h3>${esc(o.orderNo)}</h3><small>${esc(o.customerName)}</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="detail-grid"><div><span>Quotation</span><b>${esc(o.quotationNo||'—')}</b></div><div><span>Order Date</span><b>${esc(o.orderDate)}</b></div><div><span>Status</span><b>${status(o.status)}</b></div><div><span>Delivery</span><b>${status(o.deliveryStatus||'Pending')}</b></div><div><span>Invoice</span><b>${status(o.invoiceStatus||'Not Invoiced')}</b></div><div><span>Payment</span><b>${status(o.paymentStatus||'Unpaid')}</b></div></div>${table(['Product','Ordered','Delivered','Remaining','Rate','Total'],o.items.map(i=>{const delivered=(x.deliveries||[]).reduce((n,d)=>n+(d.items||[]).filter(z=>Number(z.productId)===Number(i.productId)&&Number(d.orderId)===Number(o.id)).reduce((m,z)=>m+Number(z.deliveredQty||0),0),0);return `<tr><td>${esc(i.productName)}</td><td>${i.quantity}</td><td>${delivered}</td><td>${Math.max(0,Number(i.quantity)-delivered)}</td><td>${money(i.rate)}</td><td>${money(i.total)}</td></tr>`}).join(''))}<div class="request-summary"><span>Order Total</span><strong>${money(o.total)}</strong></div></div><div class="modal-foot"><button class="btn-secondary" onclick="closeModal()">Close</button><button class="btn-primary" onclick="closeModal();openDelivery(${o.id})">Create Delivery</button><button class="btn-primary" onclick="closeModal();createCustomerInvoice(${o.id})">Create Invoice</button></div></div></div>`)}
function deliveryRemaining(x,o,item){return Math.max(0,Number(item.quantity)-((x.deliveries||[]).filter(d=>Number(d.orderId)===Number(o.id)).reduce((n,d)=>n+(d.items||[]).filter(i=>Number(i.productId)===Number(item.productId)).reduce((m,i)=>m+Number(i.deliveredQty||0),0),0)))}
function openDelivery(orderId){const x=sdb(),o=x.salesOrders.find(a=>a.id===orderId);if(!o)return;const lines=o.items.map(i=>`<div class="line-item delivery-line" data-product="${i.productId}"><b>${esc(i.productName)}</b><span>Ordered: ${i.quantity}</span><span>Remaining: ${deliveryRemaining(x,o,i)}</span><input class="d-qty" type="number" min="0" max="${deliveryRemaining(x,o,i)}" step="0.01" value="${deliveryRemaining(x,o,i)}"></div>`).join('');openModal(`<div class="modal" id="modal"><div class="modal-box request-modal"><div class="modal-head"><div><h3>Delivery — ${esc(o.orderNo)}</h3><small>${esc(o.customerName)}</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="grid2"><label>Delivery Date<input id="d-date" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Warehouse / Location<input id="d-location" placeholder="Main Warehouse"></label><label>Delivered By<input id="d-by" value="${esc(currentUser()?.name||'Admin User')}"></label><label>Delivery Reference<input id="d-ref" placeholder="Dispatch / Challan No."></label></div>${lines}<label>Notes<textarea id="d-notes" rows="2"></textarea></label></div><div class="modal-foot"><button class="btn-secondary" onclick="closeModal()">Cancel</button><button class="btn-primary" onclick="saveDelivery(${o.id})">Validate Delivery</button></div></div></div>`)}
function saveDelivery(orderId){const x=sdb(),o=x.salesOrders.find(a=>a.id===orderId);const items=[...document.querySelectorAll('.delivery-line')].map(r=>({productId:Number(r.dataset.product),productName:o.items.find(i=>Number(i.productId)===Number(r.dataset.product))?.productName||'',deliveredQty:Number(r.querySelector('.d-qty').value||0)})).filter(i=>i.deliveredQty>0);if(!items.length){toast('Enter at least one delivery quantity');return}if(items.some(i=>i.deliveredQty>deliveryRemaining(x,o,o.items.find(a=>Number(a.productId)===Number(i.productId))))){toast('Delivery exceeds remaining quantity');return}x.deliveries.unshift({id:Date.now(),deliveryNo:salesNo('DO',x.deliveries,'deliveryNo'),orderId:o.id,orderNo:o.orderNo,customerId:o.customerId,customerName:o.customerName,deliveryDate:dDate.value,location:dLocation.value.trim(),deliveredBy:dBy.value.trim(),referenceNo:dRef.value.trim(),items,status:'Delivered',notes:dNotes.value.trim(),createdAt:new Date().toISOString()});const complete=o.items.every(i=>deliveryRemaining(x,o,i)<=0);o.deliveryStatus=complete?'Delivered':'Partially Delivered';o.status=complete?'Delivered':'Partially Delivered';recordActivity(x,'Validated','Sales Deliveries','Delivery created for '+o.orderNo,'Delivery');save(x);closeModal();renderSalesDeliveries();toast('Delivery validated')}
function deliveryRows(rows){return table(['Delivery','Order','Customer','Date','Location','Status','Items','Actions'],rows.map(d=>`<tr><td><button class="link-btn" onclick="deliveryDetails(${d.id})">${esc(d.deliveryNo)}</button></td><td>${esc(d.orderNo)}</td><td>${esc(d.customerName)}</td><td>${esc(d.deliveryDate)}</td><td>${esc(d.location||'—')}</td><td>${status(d.status)}</td><td>${d.items.length}</td><td><button class="btn-sm" onclick="deliveryDetails(${d.id})">View</button></td></tr>`).join(''))}
function renderSalesDeliveries(){if(!guard('sales_deliveries'))return;const x=sdb();layout('sales-deliveries','Deliveries','Dispatch and customer delivery management',`<div class="section-card"><div class="section-head"><div><div class="section-title">Delivery List</div><div class="hint">Goods dispatched against Sales Orders</div></div></div>${deliveryRows(x.deliveries)}</div>`)}
function deliveryDetails(id){const x=sdb(),d=x.deliveries.find(a=>a.id===id);if(!d)return;openModal(`<div class="modal" id="modal"><div class="modal-box request-modal"><div class="modal-head"><div><h3>${esc(d.deliveryNo)}</h3><small>${esc(d.orderNo)} — ${esc(d.customerName)}</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="detail-grid"><div><span>Date</span><b>${esc(d.deliveryDate)}</b></div><div><span>Location</span><b>${esc(d.location||'—')}</b></div><div><span>Delivered By</span><b>${esc(d.deliveredBy||'—')}</b></div><div><span>Reference</span><b>${esc(d.referenceNo||'—')}</b></div></div>${table(['Product','Delivered Qty'],d.items.map(i=>`<tr><td>${esc(i.productName)}</td><td>${i.deliveredQty}</td></tr>`).join(''))}</div><div class="modal-foot"><button class="btn-secondary" onclick="closeModal()">Close</button></div></div></div>`)}
function createCustomerInvoice(orderId){const x=sdb(),o=x.salesOrders.find(a=>a.id===orderId);if(!o)return;if(x.customerInvoices.some(i=>Number(i.orderId)===Number(orderId)&&i.status!=='Cancelled')){toast('Invoice already exists for this order');return}const inv={id:Date.now(),invoiceNo:salesNo('INV',x.customerInvoices,'invoiceNo'),orderId:o.id,orderNo:o.orderNo,customerId:o.customerId,customerName:o.customerName,invoiceDate:new Date().toISOString().slice(0,10),dueDate:new Date(Date.now()+30*86400000).toISOString().slice(0,10),amount:o.total,status:'Posted',paidAmount:0,balance:o.total,paymentTerms:o.paymentTerms,items:structuredClone(o.items),createdAt:new Date().toISOString()};x.customerInvoices.unshift(inv);o.invoiceStatus='Invoiced';recordActivity(x,'Posted','Customer Invoices','Invoice '+inv.invoiceNo+' created for '+o.orderNo,'Customer Invoice');save(x);if(location.pathname.endsWith('sales-orders.html'))renderSalesOrders();else if(location.pathname.endsWith('sales-invoices.html'))renderSalesInvoices();toast('Customer invoice created')}
function invoiceBalance(x,i){return Math.max(0,Number(i.amount||0)-Number(i.paidAmount||0))}
function invoiceRows(rows){return table(['Invoice','Customer','Order','Invoice Date','Due Date','Amount','Paid','Balance','Status','Actions'],rows.map(i=>`<tr><td><button class="link-btn" onclick="salesInvoiceDetails(${i.id})">${esc(i.invoiceNo)}</button></td><td>${esc(i.customerName)}</td><td>${esc(i.orderNo)}</td><td>${esc(i.invoiceDate)}</td><td>${esc(i.dueDate)}</td><td>${money(i.amount)}</td><td>${money(i.paidAmount)}</td><td>${money(invoiceBalance(sdb(),i))}</td><td>${status(i.status)}</td><td>${invoiceBalance(sdb(),i)>0?`<button class="btn-sm" onclick="openCustomerPayment(${i.id})">Receive Payment</button>`:''}</td></tr>`).join(''))}
function renderSalesInvoices(){if(!guard('sales_invoices'))return;const x=sdb();layout('sales-invoices','Customer Invoices','Sales billing and receivables',`<div class="section-card"><div class="section-head"><div><div class="section-title">Customer Invoice List</div><div class="hint">Invoices generated from Sales Orders</div></div></div>${invoiceRows(x.customerInvoices)}</div>`)}
function salesInvoiceDetails(id){const x=sdb(),i=x.customerInvoices.find(a=>a.id===id);if(!i)return;openModal(`<div class="modal" id="modal"><div class="modal-box request-modal wide"><div class="modal-head"><div><h3>${esc(i.invoiceNo)}</h3><small>${esc(i.customerName)} — ${esc(i.orderNo)}</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="detail-grid"><div><span>Invoice Date</span><b>${esc(i.invoiceDate)}</b></div><div><span>Due Date</span><b>${esc(i.dueDate)}</b></div><div><span>Total</span><b>${money(i.amount)}</b></div><div><span>Paid</span><b>${money(i.paidAmount)}</b></div><div><span>Balance</span><b>${money(invoiceBalance(x,i))}</b></div><div><span>Status</span><b>${status(i.status)}</b></div></div>${table(['Product','Qty','Rate','Discount','Tax','Total'],i.items.map(a=>`<tr><td>${esc(a.productName)}</td><td>${a.quantity}</td><td>${money(a.rate)}</td><td>${a.discountPercent}%</td><td>${a.taxPercent}%</td><td>${money(a.total)}</td></tr>`).join(''))}</div><div class="modal-foot"><button class="btn-secondary" onclick="closeModal()">Close</button>${invoiceBalance(x,i)>0?`<button class="btn-primary" onclick="closeModal();openCustomerPayment(${i.id})">Receive Payment</button>`:''}</div></div></div>`)}
function openCustomerPayment(invoiceId){const x=sdb(),i=x.customerInvoices.find(a=>a.id===invoiceId);if(!i)return;openModal(formModal('Receive Customer Payment',`<div class="detail-note"><b>${esc(i.invoiceNo)} — ${esc(i.customerName)}</b><p>Outstanding balance: <strong>${money(invoiceBalance(x,i))}</strong></p></div><div class="grid2"><label>Payment Date<input id="cp-date" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Amount<input id="cp-amount" type="number" min="0.01" max="${invoiceBalance(x,i)}" step="0.01" value="${invoiceBalance(x,i)}"></label><label>Method<select id="cp-method"><option>Cash</option><option>Bank Transfer</option><option>Cheque</option><option>Card</option><option>Online</option></select></label><label>Reference No.<input id="cp-ref"></label></div><label>Notes<textarea id="cp-notes" rows="2"></textarea></label>`,'saveCustomerPayment('+invoiceId+')'))}
function saveCustomerPayment(invoiceId){const x=sdb(),i=x.customerInvoices.find(a=>a.id===invoiceId),bal=invoiceBalance(x,i),amount=Number(cpAmount.value||0);if(amount<=0||amount>bal){toast('Enter a valid payment amount');return}const p={id:Date.now(),paymentNo:salesNo('REC',x.customerPayments,'paymentNo'),invoiceId:i.id,invoiceNo:i.invoiceNo,orderNo:i.orderNo,customerId:i.customerId,customerName:i.customerName,paymentDate:cpDate.value,amount,method:cpMethod.value,referenceNo:cpRef.value.trim(),status:'Received',notes:cpNotes.value.trim(),createdAt:new Date().toISOString()};x.customerPayments.unshift(p);i.paidAmount=Number(i.paidAmount||0)+amount;i.balance=invoiceBalance(x,i);i.status=i.balance<=0?'Paid':'Partially Paid';const o=x.salesOrders.find(a=>Number(a.id)===Number(i.orderId));if(o)o.paymentStatus=i.status==='Paid'?'Paid':'Partially Paid';recordActivity(x,'Received','Customer Payments','Payment '+p.paymentNo+' received for '+i.invoiceNo,'Customer Payment');save(x);closeModal();renderSalesPayments();toast('Customer payment recorded')}
function paymentRows(rows){return table(['Receipt','Invoice','Customer','Date','Method','Reference','Amount','Status'],rows.map(p=>`<tr><td><b>${esc(p.paymentNo)}</b></td><td>${esc(p.invoiceNo)}</td><td>${esc(p.customerName)}</td><td>${esc(p.paymentDate)}</td><td>${esc(p.method)}</td><td>${esc(p.referenceNo||'—')}</td><td>${money(p.amount)}</td><td>${status(p.status)}</td></tr>`).join(''))}
function renderSalesPayments(){if(!guard('sales_payments'))return;const x=sdb();layout('sales-payments','Customer Payments','Receipts and accounts receivable collections',`<div class="section-card"><div class="section-head"><div><div class="section-title">Payment Receipts</div><div class="hint">Payments received against customer invoices</div></div></div>${paymentRows(x.customerPayments)}</div>`)}
function salesRoleMigration(){const x=db();let changed=false;if(!x.roles['Sales Manager']){x.roles['Sales Manager']={dashboard:false,requests:false,rfqs:false,quotations:false,comparison:false,orders:false,receipts:false,invoices:false,payments:false,vendors:false,products:true,reports:true,users:false,activities:true,leads:true,companies:true,crmQuotes:true,reminders:true,sales:true,sales_customers:true,sales_quotations:true,sales_orders:true,sales_deliveries:true,sales_invoices:true,sales_payments:true};changed=true}if(!x.roles.Salesperson){x.roles.Salesperson={dashboard:false,sales:true,sales_customers:true,sales_quotations:true,sales_orders:true,sales_deliveries:true,sales_invoices:false,sales_payments:false,vendors:false,products:true,requests:false,rfqs:false,quotations:false,comparison:false,orders:false,receipts:false,invoices:false,payments:false,reports:true,users:false,activities:true,leads:true,companies:true,crmQuotes:false,reminders:true};changed=true}if(changed)save(x)}
window.addEventListener('DOMContentLoaded',async()=>{await initAppState();if(!APP_STATE)return;salesRoleMigration();const p=location.pathname.split('/').pop();const pages={'sales.html':renderSalesDashboard,'customers.html':renderCustomers,'sales-quotations.html':renderSalesQuotations,'sales-orders.html':renderSalesOrders,'sales-deliveries.html':renderSalesDeliveries,'sales-invoices.html':renderSalesInvoices,'sales-payments.html':renderSalesPayments};const fn=pages[p];if(fn)fn()});

/* ===== Sales PDF / delivery / payment enhancements ===== */
function saveSalesQuotation(targetStatus){
  const x=sdb(),items=collectSalesLines();
  if(!items.length){toast('Add at least one product');return;}
  const customer=x.customers.find(c=>Number(c.id)===Number(document.getElementById('sq-customer').value));
  if(!customer){toast('Select a customer');return;}
  const q={id:Date.now(),quotationNo:salesNo('SQ',x.salesQuotations,'quotationNo'),customerId:customer.id,customerName:customer.name,customerAddress:customer.address||'',quotationDate:document.getElementById('sq-date').value,validUntil:document.getElementById('sq-valid').value||null,paymentTerms:document.getElementById('sq-terms').value,deliveryTerms:document.getElementById('sq-delivery').value.trim(),taxNote:document.getElementById('sq-taxnote').value.trim(),items,total:salesTotal(items),status:targetStatus,terms:document.getElementById('sq-termsnote').value.trim(),notes:document.getElementById('sq-notes').value.trim(),createdAt:new Date().toISOString()};
  x.salesQuotations.unshift(q);recordActivity(x,'Created','Sales Quotations','Sales quotation '+q.quotationNo+' created for '+customer.name,'Sales Quotation');save(x);closeModal();renderSalesQuotations();toast('Quotation saved as '+targetStatus);
  setTimeout(()=>downloadSalesQuotationPdf(q.id),250);
}
function salesQuotationRows(rows){return table(['Quotation','Customer','Date','Valid Until','Status','Total','Actions'],rows.map(q=>`<tr><td><button class="link-btn" onclick="salesQuotationDetails(${q.id})">${esc(q.quotationNo)}</button></td><td>${esc(q.customerName)}</td><td>${esc(q.quotationDate)}</td><td>${esc(q.validUntil||'—')}</td><td>${status(q.status)}</td><td>${money(q.total)}</td><td><button class="btn-sm" onclick="salesQuotationDetails(${q.id})"><i class="ti ti-eye"></i> View</button> <button class="btn-sm" onclick="downloadSalesQuotationPdf(${q.id})"><i class="ti ti-file-type-pdf"></i> PDF</button> ${q.status==='Sent'?`<button class="btn-sm" onclick="acceptSalesQuotation(${q.id})"><i class="ti ti-check"></i> Accept</button>`:''} ${['Draft','Sent'].includes(q.status)?`<button class="btn-sm" onclick="rejectSalesQuotation(${q.id})">Reject</button>`:''}</td></tr>`).join(''))}
function salesQuotationDetails(id){const x=sdb(),q=x.salesQuotations.find(a=>a.id===id);if(!q)return;openModal(`<div class="modal" id="modal"><div class="modal-box request-modal wide"><div class="modal-head"><div><h3>${esc(q.quotationNo)}</h3><small>Sales quotation for ${esc(q.customerName)}</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="detail-grid"><div><span>Customer</span><b>${esc(q.customerName)}</b></div><div><span>Quotation Date</span><b>${esc(q.quotationDate)}</b></div><div><span>Valid Until</span><b>${esc(q.validUntil||'—')}</b></div><div><span>Payment Terms</span><b>${esc(q.paymentTerms||'—')}</b></div><div><span>Delivery Terms</span><b>${esc(q.deliveryTerms||'—')}</b></div><div><span>Status</span><b>${status(q.status)}</b></div></div>${q.customerAddress?`<div class="detail-note"><b>Customer Address</b><p>${esc(q.customerAddress)}</p></div>`:''}${table(['Product','Description','Qty','Unit','Rate','Discount','Tax','Total'],q.items.map(i=>`<tr><td><b>${esc(i.productName)}</b></td><td>${esc(i.description||'—')}</td><td>${i.quantity}</td><td>${esc(i.unit||'—')}</td><td>${money(i.rate)}</td><td>${i.discountPercent}%</td><td>${i.taxPercent}%</td><td>${money(i.total)}</td></tr>`).join(''))}<div class="request-summary"><span>Quotation Total</span><strong>${money(q.total)}</strong></div>${q.terms?`<div class="detail-note"><b>Terms & Conditions</b><p>${esc(q.terms)}</p></div>`:''}${q.notes?`<div class="detail-note"><b>Notes</b><p>${esc(q.notes)}</p></div>`:''}</div><div class="modal-foot"><button class="btn-secondary" onclick="downloadSalesQuotationPdf(${q.id})"><i class="ti ti-file-type-pdf"></i> PDF / Print</button><button class="btn-secondary" onclick="closeModal()">Close</button>${q.status==='Sent'?`<button class="btn-primary" onclick="closeModal();acceptSalesQuotation(${q.id})">Accept & Create Order</button>`:''}</div></div></div>`)}

function openDelivery(orderId){const x=sdb(),o=x.salesOrders.find(a=>a.id===orderId);if(!o)return;const lines=o.items.map(i=>{const rem=deliveryRemaining(x,o,i);return rem>0?`<div class="line-item delivery-line" data-product="${i.productId}"><b>${esc(i.productName)}</b><span>Ordered: ${i.quantity}</span><span>Remaining: ${rem}</span><input class="d-qty" type="number" min="0" max="${rem}" step="0.01" value="${rem}"></div>`:''}).join('');if(!lines){toast('This order is fully delivered');return}openModal(`<div class="modal" id="modal"><div class="modal-box request-modal wide"><div class="modal-head"><div><h3>Validate Delivery — ${esc(o.orderNo)}</h3><small>${esc(o.customerName)}</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="grid2"><label>Delivery Date<input id="d-date" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Warehouse / Location<input id="d-location" placeholder="Main Warehouse"></label><label>Delivered By<input id="d-by" value="${esc(currentUser()?.name||'Admin User')}"></label><label>Delivery Challan No.<input id="d-ref" placeholder="Optional reference"></label></div><div class="items-head"><div><b>Delivery Items</b><small>Enter the quantity being dispatched now.</small></div></div>${lines}<label>Notes<textarea id="d-notes" rows="2"></textarea></label></div><div class="modal-foot"><button class="btn-secondary" onclick="closeModal()">Cancel</button><button class="btn-primary" onclick="saveDelivery(${o.id})"><i class="ti ti-check"></i> Validate Delivery</button></div></div></div>`)}
function saveDelivery(orderId){const x=sdb(),o=x.salesOrders.find(a=>a.id===orderId);if(!o){toast('Sales order not found');return}const items=[...document.querySelectorAll('.delivery-line')].map(r=>({productId:Number(r.dataset.product),productName:o.items.find(i=>Number(i.productId)===Number(r.dataset.product))?.productName||'',deliveredQty:Number(r.querySelector('.d-qty')?.value||0)})).filter(i=>i.deliveredQty>0);if(!items.length){toast('Enter at least one delivery quantity');return}for(const i of items){const oi=o.items.find(a=>Number(a.productId)===Number(i.productId));if(!oi||i.deliveredQty>deliveryRemaining(x,o,oi)){toast('Delivery exceeds remaining quantity for '+i.productName);return}}const d={id:Date.now(),deliveryNo:salesNo('DO',x.deliveries,'deliveryNo'),orderId:o.id,orderNo:o.orderNo,quotationId:o.quotationId,quotationNo:o.quotationNo,customerId:o.customerId,customerName:o.customerName,customerAddress:x.customers.find(c=>Number(c.id)===Number(o.customerId))?.address||'',deliveryDate:document.getElementById('d-date').value,location:document.getElementById('d-location').value.trim(),deliveredBy:document.getElementById('d-by').value.trim(),referenceNo:document.getElementById('d-ref').value.trim(),items,status:'Delivered',notes:document.getElementById('d-notes').value.trim(),createdAt:new Date().toISOString()};x.deliveries.unshift(d);const complete=o.items.every(i=>deliveryRemaining(x,o,i)<=0);o.deliveryStatus=complete?'Delivered':'Partially Delivered';o.status=complete?'Delivered':'Partially Delivered';const inv=createInvoiceFromDelivery(x,o,d);if(inv)d.invoiceId=inv.id;recordActivity(x,'Validated','Sales Deliveries','Delivery '+d.deliveryNo+' validated for '+o.orderNo,'Delivery');save(x);closeModal();renderSalesDeliveries();toast('Delivery validated');setTimeout(()=>downloadDeliveryChallanPdf(d.id),200);if(inv)setTimeout(()=>downloadSalesInvoicePdf(inv.id),700)}
function createInvoiceFromDelivery(x,o,d){const mapped=d.items.map(di=>{const oi=o.items.find(i=>Number(i.productId)===Number(di.productId));if(!oi)return null;const c=calcSalesItem(di.deliveredQty,oi.rate,oi.discountPercent,oi.taxPercent);return {...oi,quantity:di.deliveredQty,...c}}).filter(Boolean);const amount=salesTotal(mapped);if(amount<=0)return null;const inv={id:Date.now()+1,invoiceNo:salesNo('INV',x.customerInvoices,'invoiceNo'),orderId:o.id,orderNo:o.orderNo,quotationId:o.quotationId,quotationNo:o.quotationNo,deliveryId:d.id,customerId:o.customerId,customerName:o.customerName,invoiceDate:new Date().toISOString().slice(0,10),dueDate:new Date(Date.now()+30*86400000).toISOString().slice(0,10),amount,status:'Posted',paidAmount:0,balance:amount,paymentTerms:o.paymentTerms||'Cash',items:mapped,createdAt:new Date().toISOString()};x.customerInvoices.unshift(inv);o.invoiceStatus='Invoiced';recordActivity(x,'Posted','Customer Invoices','Invoice '+inv.invoiceNo+' created from delivery '+d.deliveryNo,'Customer Invoice');return inv}
function deliveryRows(rows){return table(['Delivery Challan','Order','Customer','Date','Status','Items','Actions'],rows.map(d=>`<tr><td><button class="link-btn" onclick="deliveryDetails(${d.id})">${esc(d.deliveryNo)}</button></td><td>${esc(d.orderNo)}</td><td>${esc(d.customerName)}</td><td>${esc(d.deliveryDate)}</td><td>${status(d.status)}</td><td>${d.items.length}</td><td><button class="btn-sm" onclick="deliveryDetails(${d.id})"><i class="ti ti-eye"></i> View</button> <button class="btn-sm" onclick="downloadDeliveryChallanPdf(${d.id})"><i class="ti ti-file-type-pdf"></i> Challan PDF</button>${d.invoiceId?` <button class="btn-sm" onclick="downloadSalesInvoicePdf(${d.invoiceId})"><i class="ti ti-receipt"></i> Invoice PDF</button>`:''}</td></tr>`).join(''))}
function deliveryDetails(id){const x=sdb(),d=x.deliveries.find(a=>a.id===id);if(!d)return;const o=x.salesOrders.find(a=>Number(a.id)===Number(d.orderId));openModal(`<div class="modal" id="modal"><div class="modal-box request-modal wide"><div class="modal-head"><div><h3>${esc(d.deliveryNo)}</h3><small>Delivery Challan — ${esc(d.customerName)} — ${esc(d.orderNo)}</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="detail-grid"><div><span>Delivery Date</span><b>${esc(d.deliveryDate)}</b></div><div><span>Customer</span><b>${esc(d.customerName)}</b></div><div><span>Sales Order</span><b>${esc(d.orderNo)}</b></div><div><span>Quotation</span><b>${esc(d.quotationNo||o?.quotationNo||'—')}</b></div><div><span>Location</span><b>${esc(d.location||'—')}</b></div><div><span>Delivered By</span><b>${esc(d.deliveredBy||'—')}</b></div><div><span>Reference</span><b>${esc(d.referenceNo||'—')}</b></div><div><span>Status</span><b>${status(d.status)}</b></div></div>${table(['Product','Ordered Qty','Delivered Qty','Rate','Discount','Tax','Line Total'],d.items.map(di=>{const oi=o?.items.find(i=>Number(i.productId)===Number(di.productId));return `<tr><td>${esc(di.productName)}</td><td>${oi?.quantity||'—'}</td><td><b>${di.deliveredQty}</b></td><td>${money(oi?.rate||0)}</td><td>${Number(oi?.discountPercent||0)}%</td><td>${Number(oi?.taxPercent||0)}%</td><td>${money(oi?calcSalesItem(di.deliveredQty,oi.rate,oi.discountPercent,oi.taxPercent).total:0)}</td></tr>`}).join(''))}${o?.items?.length?`<div class="detail-note"><b>Complete Quotation Items</b><p>${esc(o.items.map(i=>i.productName+' × '+i.quantity).join(' | '))}</p></div>`:''}${d.notes?`<div class="detail-note"><b>Notes</b><p>${esc(d.notes)}</p></div>`:''}</div><div class="modal-foot"><button class="btn-secondary" onclick="downloadDeliveryChallanPdf(${d.id})"><i class="ti ti-file-type-pdf"></i> Delivery Challan PDF</button>${d.invoiceId?`<button class="btn-secondary" onclick="downloadSalesInvoicePdf(${d.invoiceId})"><i class="ti ti-receipt"></i> Invoice PDF</button>`:''}<button class="btn-secondary" onclick="closeModal()">Close</button></div></div></div>`) }

function invoiceRows(rows){return table(['Invoice','Customer','Order','Invoice Date','Due Date','Amount','Paid','Balance','Status','Actions'],rows.map(i=>`<tr><td><button class="link-btn" onclick="salesInvoiceDetails(${i.id})">${esc(i.invoiceNo)}</button></td><td>${esc(i.customerName)}</td><td>${esc(i.orderNo)}</td><td>${esc(i.invoiceDate)}</td><td>${esc(i.dueDate)}</td><td>${money(i.amount)}</td><td>${money(i.paidAmount)}</td><td>${money(invoiceBalance(sdb(),i))}</td><td>${status(i.status)}</td><td><button class="btn-sm" onclick="salesInvoiceDetails(${i.id})"><i class="ti ti-eye"></i> View</button> <button class="btn-sm" onclick="downloadSalesInvoicePdf(${i.id})"><i class="ti ti-file-type-pdf"></i> PDF</button>${invoiceBalance(sdb(),i)>0?` <button class="btn-sm" onclick="openCustomerPayment(${i.id})">Receive / Partial Payment</button>`:''}</td></tr>`).join(''))}
function salesInvoiceDetails(id){const x=sdb(),i=x.customerInvoices.find(a=>a.id===id);if(!i)return;const payments=x.customerPayments.filter(p=>Number(p.invoiceId)===Number(i.id));openModal(`<div class="modal" id="modal"><div class="modal-box request-modal wide"><div class="modal-head"><div><h3>${esc(i.invoiceNo)}</h3><small>Customer Invoice — ${esc(i.customerName)} — ${esc(i.orderNo)}</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="detail-grid"><div><span>Invoice Date</span><b>${esc(i.invoiceDate)}</b></div><div><span>Due Date</span><b>${esc(i.dueDate)}</b></div><div><span>Total</span><b>${money(i.amount)}</b></div><div><span>Paid</span><b>${money(i.paidAmount)}</b></div><div><span>Balance</span><b>${money(invoiceBalance(x,i))}</b></div><div><span>Status</span><b>${status(i.status)}</b></div></div>${table(['Product','Qty','Rate','Discount','Tax','Total'],i.items.map(a=>`<tr><td>${esc(a.productName)}</td><td>${a.quantity}</td><td>${money(a.rate)}</td><td>${a.discountPercent}%</td><td>${a.taxPercent}%</td><td>${money(a.total)}</td></tr>`).join(''))}<div class="request-summary"><span>Invoice Total</span><strong>${money(i.amount)}</strong></div>${payments.length?`<div class="items-head"><div><b>Payment History</b></div></div>${paymentRows(payments)}`:''}</div><div class="modal-foot"><button class="btn-secondary" onclick="downloadSalesInvoicePdf(${i.id})"><i class="ti ti-file-type-pdf"></i> Invoice PDF</button><button class="btn-secondary" onclick="closeModal()">Close</button>${invoiceBalance(x,i)>0?`<button class="btn-primary" onclick="closeModal();openCustomerPayment(${i.id})">Receive / Partial Payment</button>`:''}</div></div></div>`)}
function openCustomerPayment(invoiceId){const x=sdb(),i=x.customerInvoices.find(a=>a.id===invoiceId);if(!i)return;const bal=invoiceBalance(x,i);openModal(formModal('Receive Customer Payment',`<div class="detail-note"><b>${esc(i.invoiceNo)} — ${esc(i.customerName)}</b><p>Outstanding balance: <strong>${money(bal)}</strong></p></div><div class="grid2"><label>Payment Date<input id="cp-date" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Payment Amount<input id="cp-amount" type="number" min="0.01" max="${bal}" step="0.01" value="${bal}"><small class="hint">Enter any amount below the outstanding balance to record a partial payment.</small></label><label>Method<select id="cp-method"><option>Cash</option><option>Bank Transfer</option><option>Cheque</option><option>Card</option><option>Online</option></select></label><label>Reference No.<input id="cp-ref"></label></div><label>Notes<textarea id="cp-notes" rows="2"></textarea></label>`,'saveCustomerPayment('+invoiceId+')'))}
function paymentRows(rows){return table(['Receipt','Invoice','Customer','Date','Method','Reference','Amount','Status','Actions'],rows.map(p=>`<tr><td><button class="link-btn" onclick="customerPaymentDetails(${p.id})"><b>${esc(p.paymentNo)}</b></button></td><td>${esc(p.invoiceNo)}</td><td>${esc(p.customerName)}</td><td>${esc(p.paymentDate)}</td><td>${esc(p.method)}</td><td>${esc(p.referenceNo||'—')}</td><td>${money(p.amount)}</td><td>${status(p.status)}</td><td><button class="btn-sm" onclick="customerPaymentDetails(${p.id})"><i class="ti ti-eye"></i> View</button> <button class="btn-sm" onclick="downloadCustomerPaymentPdf(${p.id})"><i class="ti ti-file-type-pdf"></i> PDF</button></td></tr>`).join(''))}
function customerPaymentDetails(id){const x=sdb(),p=x.customerPayments.find(a=>Number(a.id)===Number(id));if(!p)return;openModal(`<div class="modal" id="modal"><div class="modal-box request-modal"><div class="modal-head"><div><h3>${esc(p.paymentNo)}</h3><small>Customer Payment Receipt</small></div><button onclick="closeModal()">×</button></div><div class="modal-body"><div class="detail-grid">${pdfField('Receipt No.',p.paymentNo)}${pdfField('Invoice No.',p.invoiceNo)}${pdfField('Sales Order',p.orderNo)}${pdfField('Customer',p.customerName)}${pdfField('Payment Date',p.paymentDate)}${pdfField('Amount',money(p.amount))}${pdfField('Method',p.method)}${pdfField('Reference',p.referenceNo)}${pdfField('Status',p.status)}</div>${p.notes?`<div class="detail-note"><b>Notes</b><p>${esc(p.notes)}</p></div>`:''}</div><div class="modal-foot"><button class="btn-secondary" onclick="downloadCustomerPaymentPdf(${p.id})"><i class="ti ti-file-type-pdf"></i> Payment PDF</button><button class="btn-secondary" onclick="closeModal()">Close</button></div></div></div>`) }

function salesPdfBase(title,content,footer){downloadPDF(title,content+`<div class="footer">${esc(footer||'Dexterra | Sales Management')}</div>`)}
function downloadSalesQuotationPdf(id){const x=sdb(),q=x.salesQuotations.find(a=>Number(a.id)===Number(id));if(!q)return;const rows=q.items.map((i,n)=>[n+1,esc(i.productName),esc(i.description||'—'),i.quantity,esc(i.unit||'—'),money(i.rate),`${i.discountPercent}%`,`${i.taxPercent}%`,money(i.total)]);salesPdfBase(q.quotationNo,`<div class="vendor-doc-title"><h1>SALES QUOTATION</h1><p>Quotation for customer approval</p></div><div class="grid">${pdfField('Quotation No.',q.quotationNo)}${pdfField('Customer',q.customerName)}${pdfField('Quotation Date',q.quotationDate)}${pdfField('Valid Until',q.validUntil)}${pdfField('Payment Terms',q.paymentTerms)}${pdfField('Delivery Terms',q.deliveryTerms)}${pdfField('Status',q.status)}</div><div class="section"><h3>Quotation Items</h3>${pdfTable(['#','Product','Description','Qty','Unit','Rate','Discount','Tax','Total'],rows)}</div><div class="total">Quotation Total: ${money(q.total)}</div>${q.customerAddress?`<div class="note"><b>Customer Address</b><br>${esc(q.customerAddress)}</div>`:''}${q.terms?`<div class="note"><b>Terms & Conditions</b><br>${esc(q.terms)}</div>`:''}${q.notes?`<div class="note"><b>Notes</b><br>${esc(q.notes)}</div>`:''}`,'Dexterra | Sales Quotation')}
function downloadDeliveryChallanPdf(id){const x=sdb(),d=x.deliveries.find(a=>Number(a.id)===Number(id));if(!d)return;const o=x.salesOrders.find(a=>Number(a.id)===Number(d.orderId)),q=x.salesQuotations.find(a=>Number(a.id)===Number(d.quotationId||o?.quotationId));const all=q?.items||o?.items||[];const delivered={};d.items.forEach(i=>delivered[i.productId]=i.deliveredQty);const rows=all.map((i,n)=>[n+1,esc(i.productName),esc(i.description||'—'),i.quantity,esc(i.unit||'—'),delivered[i.productId]??0,money(i.rate),money(i.total)]);salesPdfBase('Delivery Challan - '+d.deliveryNo,`<div class="vendor-doc-title"><h1>DELIVERY CHALLAN</h1><p>Complete quotation with delivery details</p></div><div class="grid">${pdfField('Challan No.',d.deliveryNo)}${pdfField('Customer',d.customerName)}${pdfField('Sales Order',d.orderNo)}${pdfField('Quotation No.',d.quotationNo||q?.quotationNo)}${pdfField('Delivery Date',d.deliveryDate)}${pdfField('Location',d.location)}${pdfField('Delivered By',d.deliveredBy)}${pdfField('Reference No.',d.referenceNo)}</div><div class="section"><h3>Complete Quotation / Delivery Details</h3>${pdfTable(['#','Product','Description','Quoted Qty','Unit','Delivered Qty','Rate','Quoted Line Total'],rows)}</div><div class="note"><b>Document Purpose</b><br>This Delivery Challan is issued against the complete sales quotation and clearly identifies the quantities delivered in this dispatch.</div>${d.notes?`<div class="note"><b>Notes</b><br>${esc(d.notes)}</div>`:''}<div class="signature-row"><div class="signature">Prepared / Delivered By</div><div class="signature">Customer Acknowledgement</div></div>`,'Dexterra | Delivery Challan')}
function downloadSalesInvoicePdf(id){const x=sdb(),i=x.customerInvoices.find(a=>Number(a.id)===Number(id));if(!i)return;const rows=i.items.map((a,n)=>[n+1,esc(a.productName),esc(a.description||'—'),a.quantity,esc(a.unit||'—'),money(a.rate),`${a.discountPercent}%`,`${a.taxPercent}%`,money(a.total)]);salesPdfBase(i.invoiceNo,`<div class="vendor-doc-title"><h1>CUSTOMER INVOICE</h1><p>Sales invoice generated from delivery / sales order</p></div><div class="grid">${pdfField('Invoice No.',i.invoiceNo)}${pdfField('Customer',i.customerName)}${pdfField('Sales Order',i.orderNo)}${pdfField('Quotation',i.quotationNo)}${pdfField('Delivery',i.deliveryId)}${pdfField('Invoice Date',i.invoiceDate)}${pdfField('Due Date',i.dueDate)}${pdfField('Payment Terms',i.paymentTerms)}${pdfField('Status',i.status)}</div><div class="section"><h3>Invoice Items</h3>${pdfTable(['#','Product','Description','Qty','Unit','Rate','Discount','Tax','Total'],rows)}</div><div class="grid">${pdfField('Invoice Total',money(i.amount))}${pdfField('Paid',money(i.paidAmount))}${pdfField('Balance',money(invoiceBalance(x,i)))}</div><div class="total">Amount Due: ${money(invoiceBalance(x,i))}</div>`,'Dexterra | Customer Invoice')}
function downloadCustomerPaymentPdf(id){const x=sdb(),p=x.customerPayments.find(a=>Number(a.id)===Number(id));if(!p)return;const i=x.customerInvoices.find(a=>Number(a.id)===Number(p.invoiceId));salesPdfBase(p.paymentNo,`<div class="vendor-doc-title"><h1>CUSTOMER PAYMENT RECEIPT</h1><p>Receipt for payment received against customer invoice</p></div><div class="grid">${pdfField('Receipt No.',p.paymentNo)}${pdfField('Invoice No.',p.invoiceNo)}${pdfField('Sales Order',p.orderNo)}${pdfField('Customer',p.customerName)}${pdfField('Payment Date',p.paymentDate)}${pdfField('Payment Method',p.method)}${pdfField('Reference No.',p.referenceNo)}${pdfField('Status',p.status)}${pdfField('Invoice Total',money(i?.amount||0))}${pdfField('Invoice Paid',money(i?.paidAmount||0))}${pdfField('Invoice Balance',money(i?invoiceBalance(x,i):0))}</div><div class="total">Payment Received: ${money(p.amount)}</div>${p.notes?`<div class="note"><b>Notes</b><br>${esc(p.notes)}</div>`:''}<div class="signature-row"><div class="signature">Received By</div><div class="signature">Customer</div></div>`,'Dexterra | Customer Payment Receipt')}
